// Package edition holds the members of the newest core edition the pinned upstream release
// supports. The table is generated by scripts/edition.sh.
package edition

import (
	"sync"
	"sync/atomic"
)

// Kind of an edition member.
const (
	KindArray     = "array"
	KindLayout    = "layout"
	KindDType     = "dtype"
	KindAggregate = "aggregate"
)

// Member is one identifier a reader must know.
type Member struct {
	Kind  string
	ID    string
	Since string
}

// Members returns a copy of the table.
func Members() []Member {
	return append([]Member(nil), members...)
}

// Has reports whether the edition contains the identifier of that kind.
func Has(kind, id string) bool {
	for _, m := range members {
		if m.Kind == kind && m.ID == id {
			return true
		}
	}
	return false
}

// registries are the identifiers each package decodes, by kind. A package adds its own with
// Register in a package-level variable, so no init function is needed.
var (
	regMu      sync.Mutex
	registries = map[string][]func() []string{}
	writers    = map[string][]func() []string{}
)

// Register declares the identifiers of one kind that a package decodes. It returns true so
// that it can initialize a package-level variable.
func Register(kind string, ids func() []string) bool {
	regMu.Lock()
	defer regMu.Unlock()
	registries[kind] = append(registries[kind], ids)
	return true
}

// RegisterWritten declares the identifiers of one kind that a package writes, besides those of
// the other packages that did. It returns true so that it can initialize a package-level variable.
func RegisterWritten(kind string, ids func() []string) bool {
	regMu.Lock()
	defer regMu.Unlock()
	writers[kind] = append(writers[kind], ids)
	return true
}

// Support says, for one member of the edition, whether a registry has it.
type Support struct {
	Member
	Decoded bool
	Written bool
}

// Supported lists every member of the edition with what the registered packages decode and
// write. The generator of the README matrix uses it.
func Supported() []Support {
	regMu.Lock()
	defer regMu.Unlock()
	known, written := idSets(registries), idSets(writers)
	out := make([]Support, len(members))
	for i, m := range members {
		out[i] = Support{Member: m, Decoded: known[m.Kind][m.ID], Written: written[m.Kind][m.ID]}
	}
	return out
}

// idSets calls every registry and returns its identifiers as a set per kind.
func idSets(regs map[string][]func() []string) map[string]map[string]bool {
	out := map[string]map[string]bool{}
	for kind, fs := range regs {
		out[kind] = map[string]bool{}
		for _, ids := range fs {
			for _, id := range ids() {
				out[kind][id] = true
			}
		}
	}
	return out
}

// Missing returns the members of the edition that are not in decoded, a set per kind.
func Missing(decoded map[string]map[string]bool) []Member {
	var out []Member
	for _, m := range members {
		if !decoded[m.Kind][m.ID] {
			out = append(out, m)
		}
	}
	return out
}

// observer is told of each identifier a reader meets. Tests set it; it stays nil otherwise.
var observer atomic.Pointer[func(kind, id string)]

// Observe sets the function told of each identifier met while reading, nil to stop. It is
// for test builds: the hot path only loads a pointer.
func Observe(f func(kind, id string)) {
	if f == nil {
		observer.Store(nil)
		return
	}
	observer.Store(&f)
}

// Met tells the observer, if any, that a reader met the identifier.
func Met(kind, id string) {
	if f := observer.Load(); f != nil {
		(*f)(kind, id)
	}
}
